export const REPORT_DISCLAIMER='Aplikace MŮJ-DIP slouží pouze k obecným informačním a vzdělávacím účelům. Zobrazené částky, grafy a srovnání jsou orientační modelové scénáře, nikoli příslib budoucího výsledku, nabídka konkrétního produktu ani individuální investiční, daňové či právní poradenství. Provozovatel negarantuje dosažení uvedených výsledků, výši výnosu, návratnost vložených prostředků ani budoucí daňové úspory. Hodnota investice může růst i klesat a investor může utrpět ztrátu. Výpočty závisejí na zadaných údajích a zjednodušených předpokladech; nezahrnují všechny individuální okolnosti, náklady, daně ani zákonné výjimky. Právní předpisy, daňový režim i podmínky poskytovatelů se mohou změnit. Srovnání není úplným pořadím produktů podle výhodnosti. Před rozhodnutím ověřte aktuální právní úpravu, smluvní dokumentaci, rizika a náklady konkrétního produktu; podle potřeby využijte odborné poradenství. Rozhodnutí nečiňte pouze na základě této kalkulačky. Toto upozornění nevylučuje ani neomezuje odpovědnost provozovatele v rozsahu, v němž ji podle platných právních předpisů nelze vyloučit nebo omezit, ani zákonná práva spotřebitele.';
export const REPORT_LINKS={website:'https://muj-dip.jirijanousek.cz/',support:'https://muj-dip.jirijanousek.cz/support.php'};
const labels={own:'Vlastní vklad měsíčně (Kč)',employer:'Příspěvek firmy měsíčně na osobu (Kč)',age:'Věk při založení',years:'Doba investování (let)',initial:'Počáteční částka (Kč)',initialNew:'Nový vlastní vklad: 1 ano / 0 existující majetek',rate:'Roční výnos (%)',inflation:'Roční inflace (%)',salary:'Hrubá měsíční mzda (Kč)',otherOwn:'Jiné roční odpočty (Kč)',otherEmployer:'Jiné příspěvky firmy za rok na osobu (Kč)',employees:'Počet zaměstnanců',mode:'Režim porovnání'};
export function calculatorReport(r,kind='plan'){
 const s=r.s;
 if(!['plan','company'].includes(kind))throw Error('Neznámý modul');
 if(kind==='company'){
  const budget=s.mode==='budget';
  return {id:'firma',title:'Pro firmu – model příspěvku na DIP',subtitle:'Roční srovnání mzdy a příspěvku firmy. Částky v Kč.',summary:[['Režim',budget?'Stejný celkový rozpočet firmy':'Stejná částka příspěvku a hrubé mzdy'],['Počet zaměstnanců',s.employees],['Náklad na DIP – celý tým / rok',r.dipCost*s.employees],['Náklad na zvýšení mzdy – celý tým / rok',r.wageCost*s.employees],['Rozdíl nákladů – celý tým / rok',r.companySaving*s.employees],['Hodnota navíc na zaměstnance / rok',r.employeeDifference]],settings:['employees','salary','employer','otherEmployer','mode'].map(k=>[labels[k],s[k]]),headers:['Položka na osobu / rok','Mzda (Kč)','DIP (Kč)'],rows:[['Hrubá částka / příspěvek',r.raise,s.employer*12],['Odvody firmy navíc',r.wageCost-r.raise,r.dipCost-s.employer*12],['Náklad firmy celkem',r.wageCost,r.dipCost],['Daň a odvody zaměstnance',r.raise-r.wageNet,r.dipTaxCost],['Hodnota po dani a odvodech',r.wageNet,r.dipNetBenefit]],chart:{type:'bar',title:'Hodnota po dani a odvodech na zaměstnance / rok',categories:['Mzda na účet','DIP po odvodech'],series:[{name:'Hodnota v Kč',color:'#76283b',values:[r.wageNet,r.dipNetBenefit]}]},notes:['Čistá mzda je ihned dostupná. Příspěvek na DIP je dlouhodobá investice s omezením výběru, nikoli hotovost k běžné spotřebě.','Roční model pro běžný pracovní poměr a stejné podmínky zaměstnanců, před daní z příjmů firmy. Nezahrnuje poplatky poskytovatele ani dopad na sociální dávky a důchod.','Osvobozená část příspěvku na osobu za rok: '+r.exempt+' Kč; nadlimitní část: '+r.taxable+' Kč.'],disclaimer:REPORT_DISCLAIMER};
 }
 return {id:'plan',title:'Můj DIP – investiční plán',subtitle:'Modelová hodnota před případnou daní z investičních výnosů. Částky v Kč.',summary:[['Hodnota DIP na konci modelu',r.end.value],['Hodnota v dnešních cenách',r.end.real],['Vlastní vklady celkem',r.end.own],['Příspěvky firmy celkem',r.end.employer],['Modelové zhodnocení',r.end.gain],['Úspora daně v prvním roce',r.firstYearTax],['Odpočet v prvním roce',r.firstYearAllowance],['Věk řádného výběru nejdříve',r.eligibleAge]],settings:['own','employer','age','years','initial','initialNew','rate','inflation','salary','otherOwn'].map(k=>[labels[k],s[k]]),headers:['Rok','Věk','Vaše vklady (Kč)','Firma (Kč)','Hodnota DIP (Kč)','Zhodnocení (Kč)','Úspora daně mimo DIP (Kč)','Dnešní ceny (Kč)'],rows:r.points.map(p=>[p.year,s.age+p.year,p.own,p.employer,p.value,p.gain,p.tax,p.real]),chart:{type:'line',title:'Vývoj hodnoty DIP před případnou daní z výnosů',categories:r.points.map(p=>p.year),series:[{name:'Hodnota DIP',color:'#2563eb',values:r.points.map(p=>p.value)},{name:'Po inflaci',color:'#dc2626',values:r.points.map(p=>p.real)},{name:'Celkové vklady',color:'#708052',values:r.points.map(p=>p.own+p.employer)}]},notes:['Daňová úspora je mimo hodnotu DIP a není automaticky reinvestována. Poplatky nejsou odečítány samostatně; výnos zadávejte po nákladech.',r.eligible?'Horizont splňuje základní podmínky 120 měsíců a dosažení 60 let.':'POZOR: horizont nesplňuje obě podmínky řádného výběru. Předčasný výběr může vést k vrácení daňové podpory.','Daňové a mzdové parametry: rok 2026. Budoucí pravidla a výnosy se mohou změnit.'],disclaimer:REPORT_DISCLAIMER};
}
